import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";

/**
 * figma: Alert — State = Default | Destructive, Dir = LTR | RTL.
 * Box: px 10, py 8, gap 8, radius-lg, 1px border on `card`.
 *
 * Note the destructive alert keeps the neutral card surface and recolours the
 * text only — it does not tint the background. Tinted alerts in the file
 * (the "Custom Colors" example) are built by passing Tailwind palette classes,
 * e.g. `className="bg-amber-50 border-amber-200 text-amber-900"`.
 */
const alertVariants = cva(
  cn(
    "relative grid w-full items-start gap-y-0.5 rounded-lg border bg-card px-2.5 py-2 text-sm",
    "has-[>svg]:grid-cols-[auto_1fr] has-[>svg]:gap-x-2.5 grid-cols-[1fr]",
    "[&>svg]:size-4 [&>svg]:translate-y-0.5 [&>svg]:text-current"
  ),
  {
    variants: {
      variant: {
        default: "text-card-foreground",
        destructive: "text-text-destructive [&>[data-slot=alert-description]]:text-text-destructive/85",
      },
    },
    defaultVariants: { variant: "default" },
  }
);

function Alert({
  className,
  variant,
  ...props
}: React.ComponentProps<"div"> & VariantProps<typeof alertVariants>) {
  return (
    <div
      data-slot="alert"
      role="alert"
      className={cn(alertVariants({ variant }), className)}
      {...props}
    />
  );
}

function AlertTitle({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-title"
      className={cn(
        "col-start-2 line-clamp-1 min-h-4 font-medium tracking-tight",
        "[&:only-child]:col-start-auto",
        className
      )}
      {...props}
    />
  );
}

function AlertDescription({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-description"
      className={cn(
        "col-start-2 grid justify-items-start gap-1 text-sm font-light text-muted-foreground",
        "[&_p]:leading-relaxed",
        className
      )}
      {...props}
    />
  );
}

/** figma: the Alert page's "Action" example — a trailing button slot. */
function AlertAction({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="alert-action"
      className={cn("col-start-3 row-span-2 row-start-1 self-center ps-2.5", className)}
      {...props}
    />
  );
}

export { Alert, AlertTitle, AlertDescription, AlertAction, alertVariants };
